{
 "solicitudes": [
  {
   "id_compra": numero o null (el ID de Symphony, ej. 15889; si dicen "ID 15889" extrae 15889),
   "cuenta_cobro": "string o null",
   "remision": "string o null",
   "valor": numero o null,
   "transportista": "string o null",
   "cedula": "string o null",
   "telefono": "string o null (celular, 10 dígitos, empieza por 3)",
   "medio_pago": "NEQUI|DAVIPLATA|BANCOLOMBIA|OTRO|null",
   "tipo": "ABONO|TOTAL (TOTAL si no se especifica; ABONO si dicen abono/parcial/adelanto/ANTICIPO)"
  }
 ],
 "confianza": "ALTA|MEDIA|BAJA"
}
Reglas: punto = separador de miles (700.000 = 700000). No confundas teléfono con cédula. La REMISIÓN suele ser el mismo número del ID de compra de Symphony: si no mencionan ID explícito, usa la remisión como id_compra. Si hay varios transportistas o varias remisiones con valores distintos, crea un elemento por cada uno. Si falta un dato en un elemento, null.

MENSAJE:
' + $json.texto }] }) }}

parameters.jsCode:
let p = { solicitudes: [], confianza: 'BAJA' };
try {
  const raw = $('Extraer solicitudes con Claude').first().json.content.filter(b => b.type === 'text').map(b => b.text).join('');
  p = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {}
if (!Array.isArray(p.solicitudes)) p.solicitudes = [];
const meta = $('Recibir de WF-01 (Execute Workflow Trigger)').first().json;
const existentes = (function(){ try { return $('Leer solicitudes existentes').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const compras = (function(){ try { return $('Leer COMPRAS_SYMPHONY').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const out = [];
let seq = Date.now();
for (const s of p.solicitudes) {
  let idCompra = s.id_compra ? parseInt(String(s.id_compra).replace(/\D/g, '')) : '';
  // La remisión ES el ID de la compra en Symphony: úsala si no vino ID explícito
  if (!idCompra && s.remision) { const r = String(s.remision).replace(/\D/g, ''); if (r.length >= 4 && r.length <= 6) idCompra = parseInt(r); }
  const compra = compras.find(c => parseInt(c.ID_COMPRA) === idCompra);
  // Validación cruzada contra Symphony: existe la compra y el valor no excede lo cobrado+20%
  let avisos = [];
  if (idCompra && !compra) avisos.push('ID_COMPRA ' + idCompra + ' no existe en COMPRAS_SYMPHONY');
  if (compra && s.valor && parseFloat(compra.VALOR_DOMICILIO_COBRADO) > 0 && s.valor > parseFloat(compra.VALOR_DOMICILIO_COBRADO) * 1.2) {
    avisos.push('Valor solicitado supera en >20% lo cobrado al cliente (' + compra.VALOR_DOMICILIO_COBRADO + ')');
  }
  // Duplicado
  const dup = existentes.find(e =>
    (s.cuenta_cobro && s.remision && String(e.CUENTA_COBRO) === String(s.cuenta_cobro) && String(e.REMISION) === String(s.remision)) ||
    (idCompra && parseInt(e.ID_COMPRA) === idCompra && parseFloat(e.VALOR_SOLICITADO) === parseFloat(s.valor) && norm(e.TRANSPORTISTA) === norm(s.transportista))
  );
  function norm(x) { return String(x || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }
  const estado = dup ? 'DUPLICADO' : ((p.confianza === 'BAJA' || !s.valor) ? 'REVISAR' : 'PENDIENTE');
  out.push({ json: {
    ID_SOLICITUD: 'TRS-' + (seq++).toString().slice(-9),
    FECHA_SOLICITUD: meta.wa_timestamp.replace('T', ' ').slice(0, 16),
    SOLICITADO_POR_WA: '+' + meta.wa_from,
    ID_COMPRA: idCompra,
    CUENTA_COBRO: s.cuenta_cobro || '',
    REMISION: s.remision || '',
    TRANSPORTISTA: norm(s.transportista),
    CEDULA: s.cedula || '',
    TELEFONO: s.telefono || s.cuenta_bancaria || '',  // destino del pago: celular o cuenta bancaria
    MEDIO_PAGO: s.medio_pago || 'OTRO',
    VALOR_SOLICITADO: s.valor || '',
    ESTADO: estado,
    RETEFUENTE_APLICA: 'POR_CONFIRMAR',
    HUMAN_REVIEW: 'PENDIENTE',
    TIPO: s.tipo || 'TOTAL',
    // Retefuente transporte 1% si bruto >= 4 UVT ($209.496 en 2026 — actualizar cada año junto con CONFIG!B3)
    RETENCION: s.valor && s.valor >= 209496 ? Math.round(s.valor * 0.01) : 0,
    PAGO_NETO: s.valor ? (s.valor >= 209496 ? s.valor - Math.round(s.valor * 0.01) : s.valor) : '',
    DUPLICADO_DE: dup ? dup.ID_SOLICITUD : '',
    NOTAS: (avisos.length ? '⚠️ ' + avisos.join(' | ') + ' | ' : '') + (dup ? 'DUPLICADO de ' + dup.ID_SOLICITUD + ' | ' : '') + 'Texto: ' + (meta.texto || '').slice(0, 250)
  }});
}
if (out.length === 0) {
  out.push({ json: { ID_SOLICITUD: 'TRS-' + Date.now().toString().slice(-9), FECHA_SOLICITUD: meta.wa_timestamp.replace('T',' ').slice(0,16), SOLICITADO_POR_WA: '+' + meta.wa_from, ESTADO: 'REVISAR', HUMAN_REVIEW: 'PENDIENTE', NOTAS: 'Parser no extrajo solicitudes. Texto: ' + (meta.texto || '').slice(0, 250) } });
}
return out;

